-- SifoLending initial schema proposal. Review before applying to any database.
create extension if not exists pgcrypto;
create table if not exists public.companies(id uuid primary key default gen_random_uuid(),name text not null,currency char(3) not null default 'ZMW',created_at timestamptz not null default now());
create table if not exists public.branches(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,name text not null,created_at timestamptz not null default now(),unique(company_id,name));
create table if not exists public.borrowers(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,branch_id uuid not null references public.branches(id) on delete cascade,borrower_no text not null,full_name text not null,phone text,kyc_status text not null default 'pending' check(kyc_status in('pending','verified','rejected')),created_at timestamptz not null default now(),unique(branch_id,borrower_no));
create table if not exists public.loan_products(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,name text not null,annual_rate numeric(8,4) not null default 0 check(annual_rate>=0),term_months int not null check(term_months>0),fee_amount numeric(14,2) not null default 0 check(fee_amount>=0),active boolean not null default true);
create table if not exists public.loan_applications(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,branch_id uuid not null references public.branches(id) on delete cascade,borrower_id uuid not null references public.borrowers(id),product_id uuid not null references public.loan_products(id),principal numeric(14,2) not null check(principal>0),status text not null default 'submitted' check(status in('draft','submitted','assessment','approved','rejected','disbursed','cancelled')),created_at timestamptz not null default now());
create table if not exists public.loans(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,branch_id uuid not null references public.branches(id) on delete cascade,application_id uuid not null unique references public.loan_applications(id),principal numeric(14,2) not null check(principal>0),outstanding_principal numeric(14,2) not null check(outstanding_principal>=0),status text not null default 'active' check(status in('active','closed','arrears','written_off')),disbursed_at timestamptz);
create table if not exists public.loan_transactions(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,loan_id uuid not null references public.loans(id),transaction_type text not null check(transaction_type in('disbursement','repayment','fee','penalty','writeoff','adjustment')),amount numeric(14,2) not null check(amount>0),principal_component numeric(14,2) not null default 0,interest_component numeric(14,2) not null default 0,fee_component numeric(14,2) not null default 0,penalty_component numeric(14,2) not null default 0,reference text,posted_at timestamptz not null default now());
create table if not exists public.audit_events(id bigint generated always as identity primary key,company_id uuid not null references public.companies(id) on delete cascade,actor_id uuid,action text not null,entity_type text not null,entity_id uuid,metadata jsonb not null default '{}',created_at timestamptz not null default now());
